import Foundation

// MARK: - Evangelism Content Expansion (Entries 7–20)

extension ContentLibrary {

    static let evangelismContentExpansion: [DayContent] = [
        DayContent(
            scriptureReference: "Matthew 28:19-20",
            scriptureText: "Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit, and teaching them to obey everything I have commanded you.",
            devotionalTitle: "The Great Commission",
            devotionalText: "These aren't just Jesus' final words — they're His standing orders. 'Go and make disciples' isn't reserved for missionaries or pastors. It's for you, in your neighborhood, your workplace, your family. The word 'go' means 'as you go' — as you live your daily life. You don't need a pulpit. You need a willingness to share what God has done.",
            prayerText: "Lord Jesus, You commissioned me to make disciples. Forgive me for the times I've left that to others. As I go about my daily life, open doors for me to share Your love. Give me boldness without arrogance, and gentleness without timidity. I trust that You are with me always, even to the end of the age. Send me, Lord. In Jesus' name, amen.",
            reflectionPrompt: "If you took the Great Commission personally, what would change about your daily life?",
            actionSteps: ["Identify one person in your life who doesn't know Jesus and commit to praying for them daily", "Look for one natural opportunity today to share something God has done in your life"]
        ),
        DayContent(
            scriptureReference: "Acts 1:8",
            scriptureText: "But you will receive power when the Holy Spirit comes on you; and you will be my witnesses in Jerusalem, and in all Judea and Samaria, and to the ends of the earth.",
            devotionalTitle: "Power to Be a Witness",
            devotionalText: "Jesus didn't say 'try really hard to be my witnesses.' He said you will be — because the Holy Spirit empowers you. Witnessing isn't about having all the answers or being the most eloquent speaker. It's about testifying to what you've seen and experienced. A witness simply tells the truth about what happened. You have a story. The Spirit gives you power to share it.",
            prayerText: "Holy Spirit, fill me with power to be a witness. I don't need to be perfect — I need to be faithful. Start with my Jerusalem — the people closest to me. Then expand my vision to my community and beyond. Remove my fear and replace it with boldness. My story matters because You're the author of it. Help me share it. In Jesus' name, amen.",
            reflectionPrompt: "Who is in your 'Jerusalem' — the people closest to you who need to hear your story?",
            actionSteps: ["Write out your testimony in 3 minutes or less — what life was like before, how you met Jesus, what's different now", "Share your story with one person this week"]
        ),
        DayContent(
            scriptureReference: "Romans 1:16",
            scriptureText: "For I am not ashamed of the gospel, because it is the power of God that brings salvation to everyone who believes: first to the Jew, then to the Gentile.",
            devotionalTitle: "Unashamed",
            devotionalText: "Paul had every reason to be ashamed — the gospel got him beaten, imprisoned, and mocked. But he wasn't ashamed because he knew what the gospel could do. It's the power of God for salvation. Not a suggestion, not a philosophy — power. When you share the gospel, you're not sharing an opinion. You're offering the most powerful force in the universe. Don't be ashamed of that.",
            prayerText: "Lord, remove every ounce of shame about the gospel from my heart. I believe it is Your power for salvation. Give me courage to speak it, live it, and share it — even when it's unpopular. The gospel saved me, and it can save others. Help me remember that I'm not offering my opinion; I'm offering Your power. Make me bold and unashamed. In Jesus' name, amen.",
            reflectionPrompt: "Is there any situation where you've felt ashamed of the gospel? What was behind that feeling?",
            actionSteps: ["Practice saying 'I'm a Christian and here's why it matters to me' out loud until it feels natural", "Post or share something about your faith where others can see it"]
        ),
        DayContent(
            scriptureReference: "1 Peter 3:15",
            scriptureText: "But in your hearts revere Christ as Lord. Always be prepared to give an answer to everyone who asks you to give the reason for the hope that you have. But do this with gentleness and respect.",
            devotionalTitle: "Ready With an Answer",
            devotionalText: "Peter doesn't say prepare a sermon. He says be ready to explain your hope. People notice when you have something different — peace in chaos, joy in suffering, hope in uncertainty. When they ask why, you need to be ready. But notice the tone: gentleness and respect. Evangelism isn't about winning arguments. It's about sharing hope in a way that honors both God and the person in front of you.",
            prayerText: "Lord, set my heart on You as Lord so that my hope is obvious to those around me. Prepare me to give an answer when people ask about the hope I have. Help me share with gentleness, not aggression. With respect, not condescension. Let my life raise questions that only the gospel can answer. In Jesus' name, amen.",
            reflectionPrompt: "If someone asked you today why you have hope, what would you say?",
            actionSteps: ["Write a one-paragraph explanation of the hope you have in Christ", "Ask God to make your hope so visible that someone asks about it"]
        ),
        DayContent(
            scriptureReference: "2 Corinthians 5:20",
            scriptureText: "We are therefore Christ's ambassadors, as though God were making his appeal through us. We implore you on Christ's behalf: Be reconciled to God.",
            devotionalTitle: "Ambassador of Heaven",
            devotionalText: "An ambassador represents their home country in a foreign land. You are Christ's ambassador — representing heaven in a world that desperately needs to hear from God. And here's the stunning part: God makes His appeal through you. Not around you. Through you. Your words, your kindness, your presence become the vehicle for God's invitation to the world.",
            prayerText: "Lord, I accept my role as Your ambassador. Speak through me today. Let my words carry Your invitation and my life reflect Your character. Help me represent You well — with integrity, compassion, and truth. I implore the people around me on Your behalf: be reconciled to God. Use me as Your mouthpiece and Your hands. In Jesus' name, amen.",
            reflectionPrompt: "How well are you representing Christ in the environments where you spend most of your time?",
            actionSteps: ["Identify the 'foreign land' where God has placed you (work, school, neighborhood) and pray for it", "Represent Christ to one person today through an act of unexpected kindness"]
        ),
        DayContent(
            scriptureReference: "Matthew 5:14-16",
            scriptureText: "You are the light of the world. A town built on a hill cannot be hidden. Neither do people light a lamp and put it under a bowl. Instead they put it on its stand, and it gives light to everyone in the house.",
            devotionalTitle: "Don't Hide Your Light",
            devotionalText: "Jesus doesn't say you should be the light — He says you are the light. It's your identity, not your aspiration. But light only matters when it shines. A lamp under a bowl helps no one. Your faith, your story, your transformed life — these are meant to be visible. Not for your glory, but so that people see your good deeds and glorify your Father in heaven.",
            prayerText: "Lord, You've made me a light in this dark world. Help me stop hiding under bowls of fear, insecurity, or comfort. Let my light shine — in my words, my actions, and my character. I want people to see my life and glorify You. Give me courage to be visible and humility to point every ray of light back to You. In Jesus' name, amen.",
            reflectionPrompt: "Where have you been hiding your light, and what would it look like to let it shine?",
            actionSteps: ["Do one visible act of faith today that others can see", "Identify one 'bowl' that's been covering your light and remove it"]
        ),
        DayContent(
            scriptureReference: "Colossians 4:5-6",
            scriptureText: "Be wise in the way you act toward outsiders; make the most of every opportunity. Let your conversation be always full of grace, seasoned with salt, so that you may know how to answer everyone.",
            devotionalTitle: "Grace-Seasoned Words",
            devotionalText: "Paul gives a masterclass in evangelism in two verses. Be wise — don't be reckless or insensitive. Make the most of every opportunity — stay alert, not passive. Season your words with grace and salt — grace makes truth palatable, and salt makes it memorable. Evangelism isn't about saying everything at once. It's about saying the right thing at the right time in the right way.",
            prayerText: "Lord, make me wise in how I interact with people who don't know You. Help me see opportunities I would normally miss. Season my conversations with grace — let my words be kind, truthful, and compelling. Give me the discernment to know when to speak and when to listen. Make the most of every moment through me. In Jesus' name, amen.",
            reflectionPrompt: "Think of a recent conversation with someone far from God. Was it seasoned with grace?",
            actionSteps: ["Practice starting spiritual conversations naturally by asking people what they believe and listening", "Before your next conversation with a non-believer, pray for wisdom and grace"]
        ),
        DayContent(
            scriptureReference: "Romans 10:14-15",
            scriptureText: "How, then, can they call on the one they have not believed in? And how can they believe in the one of whom they have not heard? And how can they hear without someone preaching to them? And how can they preach unless they are sent?",
            devotionalTitle: "Someone Has to Go",
            devotionalText: "Paul lays out a chain that leads to salvation — and every link requires a person. Someone has to be sent. Someone has to speak. Someone has to share. That someone might be you. The person in your life who doesn't know God can't believe in someone they've never heard about. Your voice, your story, your willingness to speak — it matters more than you know.",
            prayerText: "Lord, send me. I'm willing to be the voice that someone needs to hear. Help me understand that faith comes by hearing, and hearing comes through people like me. Give me urgency without anxiety, boldness without pride. The people around me need to hear about You. Don't let my silence be the reason someone never hears the gospel. In Jesus' name, amen.",
            reflectionPrompt: "Is there someone in your life who might never hear the gospel unless you share it?",
            actionSteps: ["Write down the name of one person who needs to hear about Jesus and commit to sharing with them", "Pray for that person by name every day this week"]
        ),
        DayContent(
            scriptureReference: "Mark 16:15",
            scriptureText: "He said to them, 'Go into all the world and preach the gospel to all creation.'",
            devotionalTitle: "All the World Starts Next Door",
            devotionalText: "'All the world' sounds overwhelming — but it starts with the person next to you. Your neighbor, your coworker, the barista who makes your coffee. The gospel spreads one conversation at a time, one relationship at a time. You don't need a plane ticket to obey this command. You need open eyes and a willing heart right where you are.",
            prayerText: "Lord, expand my vision of 'all the world' to include the people right in front of me. Help me see my daily interactions as mission opportunities. The grocery store, the office, the school pickup line — these are my mission fields. Give me the courage to share Your good news wherever I go. In Jesus' name, amen.",
            reflectionPrompt: "Who are the people you see regularly who might not know Jesus?",
            actionSteps: ["Map your weekly routine and identify where you regularly encounter people who need Jesus", "Start a conversation with someone you see regularly but have never talked to about faith"]
        ),
        DayContent(
            scriptureReference: "Isaiah 52:7",
            scriptureText: "How beautiful on the mountains are the feet of those who bring good news, who proclaim peace, who bring good tidings, who proclaim salvation, who say to Zion, 'Your God reigns!'",
            devotionalTitle: "Beautiful Feet",
            devotionalText: "In ancient times, messengers ran across mountains to deliver news of victory. Isaiah says their feet are beautiful — not because of their appearance, but because of the message they carry. When you share the gospel, you're carrying the greatest news in human history: God reigns, peace is available, salvation has come. Your willingness to deliver this message makes you beautiful in God's eyes.",
            prayerText: "Lord, give me beautiful feet — feet that carry good news wherever they go. I want to proclaim peace, bring good tidings, and declare that You reign. Help me see sharing the gospel not as a burden but as a privilege. I carry the most important message in the world. Let me deliver it with joy. In Jesus' name, amen.",
            reflectionPrompt: "Do you see sharing the gospel as a burden or a privilege? What shapes that perspective?",
            actionSteps: ["Share one piece of good news about God with someone today", "Pray that God would give you a fresh sense of privilege about carrying His message"]
        ),
        DayContent(
            scriptureReference: "Acts 4:29-31",
            scriptureText: "Now, Lord, consider their threats and enable your servants to speak your word with great boldness. Stretch out your hand to heal and perform signs and wonders through the name of your holy servant Jesus.",
            devotionalTitle: "Pray for Boldness",
            devotionalText: "The early church faced real threats for sharing their faith. Their response? They didn't pray for safety — they prayed for boldness. And the room shook. When you feel intimidated about sharing your faith, don't pray for the fear to go away. Pray for boldness that's bigger than the fear. God answers that prayer. He always has.",
            prayerText: "Lord, I don't pray for a life without opposition. I pray for boldness that overcomes it. Enable me to speak Your word with great courage. When I face rejection or ridicule, fill me with even more boldness. Stretch out Your hand and confirm Your word with power. Shake the room, Lord. Shake my fear. Make me fearless for Your name. In Jesus' name, amen.",
            reflectionPrompt: "What would you do for God if you weren't afraid?",
            actionSteps: ["Pray specifically for boldness before your next opportunity to share your faith", "Take one faith step today that scares you a little"]
        ),
        DayContent(
            scriptureReference: "2 Timothy 4:2",
            scriptureText: "Preach the word; be prepared in season and out of season; correct, rebuke and encourage — with great patience and careful instruction.",
            devotionalTitle: "In Season and Out",
            devotionalText: "Paul's charge to Timothy applies to every believer: be ready — whether the timing feels right or not. 'In season' is when it's easy and people are receptive. 'Out of season' is when it's hard, awkward, or unwelcome. Faithful witnesses don't wait for perfect conditions. They share with patience and care, trusting God with the results. Your job is to sow; God's job is to grow.",
            prayerText: "Lord, help me be prepared to share Your word in every season — when it's easy and when it's hard. Give me patience with people who aren't ready and wisdom with people who are. I trust You with the results. My job is faithfulness; the harvest is Yours. Help me sow generously and trust You completely. In Jesus' name, amen.",
            reflectionPrompt: "Are you more comfortable sharing your faith 'in season' or do you also step up 'out of season'?",
            actionSteps: ["Prepare a brief version of your testimony you can share in any situation", "Share something about your faith today even if the timing doesn't feel perfect"]
        ),
        DayContent(
            scriptureReference: "Philemon 1:6",
            scriptureText: "I pray that your partnership in the faith may be effective, so that you will have a full understanding of every good thing we share for the sake of Christ.",
            devotionalTitle: "Sharing Deepens Understanding",
            devotionalText: "Here's a truth most Christians miss: sharing your faith doesn't just benefit others — it deepens your own understanding of God. When you articulate what you believe, you understand it more fully. When you see God work through your words, your faith grows stronger. Evangelism isn't just giving away something you have; it's discovering more of what you've been given.",
            prayerText: "Lord, make my sharing of faith effective. As I tell others about You, deepen my own understanding of Your goodness. Help me see that evangelism isn't just an obligation — it's a pathway to deeper knowledge of You. Open my eyes to every good thing we share for the sake of Christ. Let sharing become a joy, not a duty. In Jesus' name, amen.",
            reflectionPrompt: "How has sharing your faith in the past helped you understand God better?",
            actionSteps: ["After sharing your faith with someone, journal about what you learned in the process", "Ask God to show you a 'good thing' about the gospel you haven't fully appreciated yet"]
        ),
        DayContent(
            scriptureReference: "John 20:21",
            scriptureText: "Again Jesus said, 'Peace be with you! As the Father has sent me, I am sending you.'",
            devotionalTitle: "Sent Like Jesus",
            devotionalText: "Jesus was sent by the Father with a specific mission: to seek and save the lost. Now He sends you with the same mission and the same peace. 'As the Father sent me' — with compassion, with purpose, with love. You're not just volunteering for God's mission; you're continuing the work Jesus started. He sends you with peace, not pressure. Go with confidence.",
            prayerText: "Jesus, You send me as the Father sent You — with peace, purpose, and power. I accept this sending. Help me go as You went: with compassion for the broken, truth for the searching, and love for the lost. I don't go in my own strength but in Yours. Peace be with me as I carry Your mission forward. In Jesus' name, amen.",
            reflectionPrompt: "What does it mean to you personally that Jesus sends you the same way the Father sent Him?",
            actionSteps: ["Meditate on John 20:21 and ask Jesus where He's sending you today", "Go to one place this week with the specific intention of being 'sent' by Jesus"]
        ),
    ]
}
